192	    /// active run (`Arc::strong_count == 1`) is pruned, keeping the map bounded.
193	    pub(crate) fn lock_for(&self, id: Option<&str>) -> Arc<tokio::sync::Mutex<()>> {
194	        let Some(id) = id else {
195	            return Arc::new(tokio::sync::Mutex::new(()));
196	        };
197	
