200	        // run is keeping the lock alive). An entry for `id` that is currently in
201	        // use (count > 1) is preserved, so concurrent same-id requests keep
202	        // serialising on a pointer-equal lock.
203	        map.retain(|_, lock| Arc::strong_count(lock) > 1);
204	        Arc::clone(
205	            map.entry(id.to_owned())
206	                .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(()))),
207	        )
208	    }
