224	    use super::*;
225	
226	    #[tokio::test]
227	    async fn same_id_returns_same_session_none_is_fresh() {
228	        let p = InMemorySessionProvider::new(16);
229	        let a = p.session(Some("s1")).await.unwrap();
230	        let b = p.session(Some("s1")).await.unwrap();
231	        assert!(Arc::ptr_eq(&a, &b));
232	        let anon1 = p.session(None).await.unwrap();
233	        let anon2 = p.session(None).await.unwrap();
234	        assert!(!Arc::ptr_eq(&anon1, &anon2)); // anonymous never shared / never stored
235	    }
236	
237	    #[tokio::test]
238	    async fn bounded_map_evicts() {
239	        let p = InMemorySessionProvider::new(1);
240	        let _a = p.session(Some("s1")).await.unwrap();
241	        let _b = p.session(Some("s2")).await.unwrap(); // evicts s1
242	        assert_eq!(p.len(), 1); // expose a test-only len()
243	    }
244	
245	    #[test]
246	    fn session_locks_same_id_ptr_eq() {
247	        let locks = SessionLocks::new();
248	        let l1 = locks.lock_for(Some("x"));
249	        let l2 = locks.lock_for(Some("x"));
250	        assert!(Arc::ptr_eq(&l1, &l2));
251	    }
252	
253	    #[test]
254	    fn session_locks_none_distinct() {
255	        let locks = SessionLocks::new();
256	        let l1 = locks.lock_for(None);
257	        let l2 = locks.lock_for(None);
258	        assert!(!Arc::ptr_eq(&l1, &l2));
259	    }
260	
261	    /// Once the only `Arc` to a session's lock is dropped, the next `lock_for`
262	    /// call prunes the now-unheld entry, keeping the map bounded.
263	    #[test]
264	    fn session_locks_prune_drops_unheld_entries() {
265	        let locks = SessionLocks::new();
266	
267	        // Take and release the lock Arc for "a": after the scope, only the map
268	        // holds it (strong_count == 1).
269	        {
270	            let _la = locks.lock_for(Some("a"));
271	            assert_eq!(locks.len(), 1);
272	        }
273	
274	        // Acquiring a lock for a different id prunes the now-unheld "a" entry.
275	        let _lb = locks.lock_for(Some("b"));
276	        assert_eq!(locks.len(), 1); // only "b" remains; "a" was pruned
277	
278	        // Sanity: a still-held entry is NOT pruned by a later call.
279	        let _lb_alias = locks.lock_for(Some("b"));
280	        assert!(Arc::ptr_eq(&_lb, &_lb_alias));
281	        assert_eq!(locks.len(), 1);
282	    }
283	}
