1	//! Run registry: in-flight and recently-completed runs, with TTL and count-cap retention.
2	//!
3	//! [`RunRegistry`] stores every run that was started by the axum server. Completed runs are
4	//! retained until they age out (TTL) or until the retained-run count exceeds `max_runs`
5	//! (FIFO-by-completion eviction). Live (non-terminal) runs are **never** evicted.
6	
7	use crate::event_log::EventLog;
8	use paigasus_helikon_core::AgentEvent;
9	use std::{
10	    collections::{HashMap, VecDeque},
11	    sync::{Arc, Mutex, RwLock},
12	    time::{Duration, Instant},
13	};
14	use tokio::sync::OnceCell;
15	use tokio_util::sync::CancellationToken;
16	use uuid::Uuid;
17	
18	// ── RunHandle ─────────────────────────────────────────────────────────────────
19	
20	/// Everything the server needs to track a single run.
21	pub(crate) struct RunHandle {
22	    /// Name of the agent that owns this run.
23	    pub agent_name: String,
24	    /// Append-only, bounded event log for this run.
25	    pub log: Arc<EventLog>,
26	    /// Cancellation token — drop or call `.cancel()` to abort the run.
27	    pub cancel: CancellationToken,
28	    /// Populated on the start-error path when the agent failed to launch before emitting any events.
29	    pub start_error: Mutex<Option<String>>,
30	    /// Set once the run enters a terminal state (via [`RunRegistry::note_terminal`]).
31	    pub terminal_at: Mutex<Option<Instant>>,
32	}
33	
34	impl RunHandle {
35	    /// The synthetic terminal frame a streaming transport must emit when its
36	    /// subscribe stream ended without delivering a real `RunCompleted`/`RunFailed`.
37	    ///
38	    /// Returns `None` when a real terminal was already delivered (`saw_terminal`
39	    /// is `true`). Otherwise returns an [`AgentEvent::RunFailed`], sourced from
40	    /// [`start_error`](RunHandle#structfield.start_error) if the run failed to
41	    /// start, or a generic message (e.g. a stream that panicked or ended mid-run
42	    /// before any terminal event).
43	    pub(crate) fn synthetic_terminal_frame(&self, saw_terminal: bool) -> Option<AgentEvent> {
44	        if saw_terminal {
45	            return None;
46	        }
47	        let error = self
48	            .start_error
49	            .lock()
50	            .expect("start_error mutex poisoned")
51	            .clone()
52	            .unwrap_or_else(|| "run ended before producing a terminal event".to_owned());
53	        tracing::warn!(
54	            agent = %self.agent_name,
55	            %error,
56	            "run ended without a real terminal event; synthesizing a RunFailed frame for the stream subscriber"
57	        );
58	        Some(AgentEvent::RunFailed { error })
59	    }
60	}
61	
62	// ── RegistryInner ─────────────────────────────────────────────────────────────
63	
64	/// Mutable state inside [`RunRegistry`], protected by an [`RwLock`].
65	struct RegistryInner {
66	    /// All live and recently-completed runs, keyed by run id.
67	    runs: HashMap<Uuid, Arc<RunHandle>>,
68	    /// Insertion order of terminal runs (oldest → newest). Used for FIFO eviction.
69	    completion_order: VecDeque<Uuid>,
70	}
71	
72	// ── RunRegistry ───────────────────────────────────────────────────────────────
73	
74	/// Registry of in-flight and recently-completed runs with TTL and count-cap retention.
75	///
76	/// Always constructed behind an [`Arc`] (see [`RunRegistry::new`]).
77	pub(crate) struct RunRegistry {
78	    inner: RwLock<RegistryInner>,
79	    /// How long a completed run is retained after becoming terminal.
80	    ttl: Duration,
81	    /// Maximum number of *completed* runs to retain simultaneously.
82	    max_runs: usize,
83	    /// [`EventLog`] capacity for each newly-created run.
84	    max_events_per_run: usize,
85	    /// Guards [`RunRegistry::spawn_sweeper`] so at most one background task is spawned.
86	    sweeper_once: OnceCell<()>,
87	}
88	
89	impl RunRegistry {
90	    /// Create a new registry wrapped in an [`Arc`].
91	    ///
92	    /// * `ttl` – retention window after a run becomes terminal.
93	    /// * `max_runs` – cap on retained completed runs; oldest-completed runs are evicted first.
94	    /// * `max_events_per_run` – passed to each run's [`EventLog::new`].
95	    pub fn new(ttl: Duration, max_runs: usize, max_events_per_run: usize) -> Arc<Self> {
96	        Arc::new(Self {
97	            inner: RwLock::new(RegistryInner {
98	                runs: HashMap::new(),
99	                completion_order: VecDeque::new(),
100	            }),
101	            ttl,
102	            max_runs,
103	            max_events_per_run,
104	            sweeper_once: OnceCell::new(),
105	        })
106	    }
107	
108	    /// Mint a new run id, build its handle, insert it into the registry, and return both.
109	    ///
110	    /// The run starts as non-terminal. Call [`note_terminal`](RunRegistry::note_terminal) once
111	    /// the run ends.
112	    pub fn create(&self, agent_name: String, cancel: CancellationToken) -> (Uuid, Arc<RunHandle>) {
113	        let id = Uuid::new_v4();
114	        let handle = Arc::new(RunHandle {
115	            agent_name,
116	            log: Arc::new(EventLog::new(self.max_events_per_run)),
117	            cancel,
118	            start_error: Mutex::new(None),
119	            terminal_at: Mutex::new(None),
120	        });
121	        let mut inner = self.inner.write().expect("RunRegistry RwLock poisoned");
122	        inner.runs.insert(id, Arc::clone(&handle));
123	        (id, handle)
124	    }
125	
126	    /// Look up a run by id. Returns `None` if it has been evicted or never existed.
127	    pub fn get(&self, id: Uuid) -> Option<Arc<RunHandle>> {
128	        let inner = self.inner.read().expect("RunRegistry RwLock poisoned");
129	        inner.runs.get(&id).cloned()
130	    }
131	
132	    /// Stamp the run as terminal at `now` and record it in the completion queue.
133	    ///
134	    /// Idempotent: calling more than once for the same id is a no-op after the first call.
135	    /// `now` is passed explicitly so callers can inject a deterministic clock in tests.
136	    pub fn note_terminal(&self, id: Uuid, now: Instant) {
137	        // Stamp `terminal_at` and enqueue into `completion_order` in ONE critical
138	        // section so a concurrent `sweep` cannot observe a half-applied state
139	        // (stamped-but-not-enqueued, or vice versa). Lock order is `inner` →
140	        // `terminal_at`, matching `sweep`, so the two never deadlock.
141	        let mut inner = self.inner.write().expect("RunRegistry RwLock poisoned");
142	        let Some(handle) = inner.runs.get(&id).cloned() else {
143	            return;
144	        };
145	        let mut t = handle
146	            .terminal_at
147	            .lock()
148	            .expect("terminal_at mutex poisoned");
149	        if t.is_none() {
150	            *t = Some(now);
151	            inner.completion_order.push_back(id);
152	        }
153	    }
154	
155	    /// Evict stale runs in two passes.
156	    ///
157	    /// **Pass 1 – TTL:** remove every terminal run whose `terminal_at + ttl ≤ now`.
158	    ///
159	    /// **Pass 2 – count cap:** while the number of still-present *terminal* runs exceeds
160	    /// `max_runs`, pop the front of the completion queue and evict it (skipping ids that
161	    /// were already removed by pass 1 or a previous cap iteration).
162	    ///
163	    /// Live (non-terminal) runs are **never** evicted by either pass.
164	    ///
165	    /// `now` is passed explicitly so callers can inject a deterministic clock in tests.
166	    pub fn sweep(&self, now: Instant) {
167	        let mut inner = self.inner.write().expect("RunRegistry RwLock poisoned");
168	        let ttl = self.ttl;
169	
170	        // Pass 1: TTL eviction. Track evicted ids so we can also clean them from
171	        // `completion_order`, preventing unbounded deque growth across long uptimes.
172	        let mut evicted: std::collections::HashSet<Uuid> = std::collections::HashSet::new();
173	        inner.runs.retain(|id, handle| {
174	            let t = handle
175	                .terminal_at
176	                .lock()
177	                .expect("terminal_at mutex poisoned");
178	            match *t {
179	                // Keep if still within the TTL window or non-terminal. `checked_add`
180	                // rather than `+`: an overflowing deadline would panic here while the
181	                // write lock is held, poisoning the `RwLock` for every later caller.
182	                // An un-representable deadline is infinitely far away, so keep the run.
183	                Some(terminal_at)
184	                    if terminal_at
185	                        .checked_add(ttl)
186	                        .is_some_and(|deadline| deadline <= now) =>
187	                {
188	                    evicted.insert(*id);
189	                    false
190	                }
191	                _ => true,
192	            }
193	        });
194	        // Remove TTL-evicted ids from the completion queue to prevent memory leaks.
195	        if !evicted.is_empty() {
196	            inner.completion_order.retain(|id| !evicted.contains(id));
197	        }
198	
199	        // Pass 2: count-cap eviction (FIFO by completion order).
200	        let mut terminal_count = inner
201	            .runs
202	            .values()
203	            .filter(|h| {
204	                h.terminal_at
205	                    .lock()
206	                    .expect("terminal_at mutex poisoned")
207	                    .is_some()
208	            })
209	            .count();
210	
211	        while terminal_count > self.max_runs {
212	            // Pop from the front; skip ids already evicted (by pass 1 or an earlier iteration).
213	            let candidate = loop {
214	                match inner.completion_order.pop_front() {
215	                    None => break None,
216	                    Some(id) if inner.runs.contains_key(&id) => break Some(id),
217	                    Some(_already_gone) => continue,
218	                }
219	            };
220	            match candidate {
221	                None => break, // Safety valve: no more candidates.
222	                Some(id) => {
223	                    inner.runs.remove(&id);
224	                    terminal_count -= 1;
225	                }
226	            }
227	        }
228	    }
229	
230	    /// Spawn a background task that calls [`sweep`](RunRegistry::sweep) every 30 seconds.
231	    ///
232	    /// At most one task is spawned per registry instance (guarded by a [`OnceCell`]).
233	    /// The task holds a [`Weak`] reference so it automatically exits when the registry is dropped
234	    /// (i.e., no [`Arc`] remainders outside the spawned task itself).
235	    pub fn spawn_sweeper(self: &Arc<Self>) {
236	        // `OnceCell::set` succeeds exactly once; subsequent calls return `Err` which we ignore.
237	        if self.sweeper_once.set(()).is_ok() {
238	            let weak = Arc::downgrade(self);
239	            tokio::spawn(async move {
240	                let mut interval = tokio::time::interval(Duration::from_secs(30));
241	                loop {
242	                    interval.tick().await;
243	                    match weak.upgrade() {
244	                        None => return, // Registry dropped; exit.
245	                        Some(reg) => reg.sweep(Instant::now()),
246	                    }
247	                }
248	            });
249	        }
250	    }
251	}
252	
253	// ── Test helpers ──────────────────────────────────────────────────────────────
254	
255	#[cfg(test)]
256	impl RunRegistry {
257	    /// Returns the current length of `completion_order` for leak-regression tests.
258	    fn completion_queue_len(&self) -> usize {
259	        self.inner.read().unwrap().completion_order.len()
260	    }
261	}
262	
263	// ── Tests ─────────────────────────────────────────────────────────────────────
264	
265	#[cfg(test)]
266	mod tests {
267	    use super::*;
268	
269	    /// A completed run must not be evicted before its TTL expires, and must be evicted
270	    /// once the clock has advanced past `terminal_at + ttl`.
271	    #[test]
272	    fn ttl_evicts_after_deadline() {
273	        let reg = RunRegistry::new(Duration::from_secs(60), 1024, 1024);
274	        let (id, _h) = reg.create("a".into(), CancellationToken::new());
275	        let t0 = Instant::now();
276	        reg.note_terminal(id, t0);
277	        reg.sweep(t0 + Duration::from_secs(59));
278	        assert!(reg.get(id).is_some());
279	        reg.sweep(t0 + Duration::from_secs(61));
280	        assert!(reg.get(id).is_none());
281	    }
282	
283	    /// When the number of completed runs exceeds `max_runs`, the oldest-completed run must be
284	    /// evicted first, regardless of which run finished last.
285	    #[test]
286	    fn count_cap_evicts_oldest_completed_first() {
287	        let reg = RunRegistry::new(Duration::from_secs(3600), 2, 1024);
288	        let t0 = Instant::now();
289	        let ids: Vec<_> = (0..3)
290	            .map(|i| {
291	                let (id, _) = reg.create("a".into(), CancellationToken::new());
292	                reg.note_terminal(id, t0 + Duration::from_secs(i));
293	                id
294	            })
295	            .collect();
296	        reg.sweep(t0 + Duration::from_secs(3));
297	        assert!(reg.get(ids[0]).is_none()); // oldest-completed evicted
298	        assert!(reg.get(ids[1]).is_some()); // middle run survives (exactly one evicted)
299	        assert!(reg.get(ids[2]).is_some());
300	    }
301	
302	    /// TTL eviction must also remove the evicted ids from `completion_order` so that the
303	    /// deque does not grow without bound across long server uptimes (regression for the
304	    /// completion-queue leak found in review).
305	    #[test]
306	    fn ttl_eviction_cleans_completion_queue() {
307	        let reg = RunRegistry::new(Duration::from_secs(60), 1024, 1024);
308	        let t0 = Instant::now();
309	
310	        // Create and terminate three runs.
311	        for _ in 0..3 {
312	            let (id, _h) = reg.create("a".into(), CancellationToken::new());
313	            reg.note_terminal(id, t0);
314	        }
315	        assert_eq!(reg.completion_queue_len(), 3);
316	
317	        // Sweep before TTL — nothing evicted, queue unchanged.
318	        reg.sweep(t0 + Duration::from_secs(59));
319	        assert_eq!(reg.completion_queue_len(), 3);
320	
321	        // Sweep past TTL — all three runs evicted and queue must be empty.
322	        reg.sweep(t0 + Duration::from_secs(61));
323	        assert_eq!(reg.completion_queue_len(), 0);
324	    }
325	
326	    /// `synthetic_terminal_frame` returns `None` once a real terminal was seen,
327	    /// the captured `start_error` when present, and a generic message otherwise.
328	    #[test]
329	    fn synthetic_terminal_frame_branches() {
330	        let reg = RunRegistry::new(Duration::from_secs(60), 16, 16);
331	        let (_id, h) = reg.create("a".into(), CancellationToken::new());
332	
333	        assert!(h.synthetic_terminal_frame(true).is_none());
334	
335	        match h.synthetic_terminal_frame(false) {
336	            Some(AgentEvent::RunFailed { error }) => {
337	                assert_eq!(error, "run ended before producing a terminal event");
338	            }
339	            other => panic!("expected generic RunFailed, got {other:?}"),
340	        }
341	
342	        *h.start_error.lock().unwrap() = Some("boom".to_owned());
343	        match h.synthetic_terminal_frame(false) {
344	            Some(AgentEvent::RunFailed { error }) => assert_eq!(error, "boom"),
345	            other => panic!("expected RunFailed(boom), got {other:?}"),
346	        }
347	    }
348	}
