1	//! Cross-runtime HTTP wire-format conformance.
2	//!
3	//! Boots the `paigasus-helikon-runtime-axum` and `paigasus-helikon-runtime-actix`
4	//! servers with the SAME [`scripted_agents`] set and asserts that every
5	//! user-facing HTTP surface matches between the two runtimes — byte-identical
6	//! where the wire format is fully determined, structurally equal where a field
7	//! is legitimately per-run (a `run_id`) or order-nondeterministic (a HashMap of
8	//! agents).
9	//!
10	//! The two servers are booted with the two different runtime models on purpose:
11	//! axum via `tokio::spawn` on the test's own runtime; actix via a dedicated OS
12	//! thread driving its own `actix_web::rt::System`.
13	
14	use paigasus_helikon_runtime_http_conformance::scripted_agents;
15	
16	/// A fixed token substituted for the per-run UUID before a byte comparison.
17	const RUN_ID_TOKEN: &str = "<RUN_ID>";
18	
19	/// Boot the axum runtime on an ephemeral loopback port and return its base URL.
20	///
21	/// The serve loop is spawned as a task on the caller's tokio runtime, matching
22	/// the axum runtime's documented embedding model.
23	async fn boot_axum() -> String {
24	    let mut builder =
25	        paigasus_helikon_runtime_axum::AgentServer::<()>::builder().with_default_context();
26	    for agent in scripted_agents() {
27	        builder = builder.agent(agent);
28	    }
29	    let server = builder.build().expect("axum server builds");
30	
31	    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
32	        .await
33	        .expect("bind ephemeral port");
34	    let addr = listener.local_addr().expect("local addr");
35	    tokio::spawn(async move {
36	        server
37	            .serve_with_listener(listener)
38	            .await
39	            .expect("axum serve loop");
40	    });
41	    format!("http://{addr}")
42	}
43	
44	/// Boot the actix runtime on an ephemeral loopback port and return its base URL.
45	///
46	/// actix-web owns a non-`Send` per-worker runtime, so — unlike axum — the serve
47	/// loop cannot be a task on the test's runtime. The listener is bound on the
48	/// calling thread, then the serve loop is driven from an `actix_web::rt::System`
49	/// created on a dedicated OS thread. A brief readiness wait lets the accept loop
50	/// come up before the first connection attempt.
51	fn boot_actix() -> String {
52	    let mut builder =
53	        paigasus_helikon_runtime_actix::AgentServer::<()>::builder().with_default_context();
54	    for agent in scripted_agents() {
55	        builder = builder.agent(agent);
56	    }
57	    let server = builder.build().expect("actix server builds");
58	
59	    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind ephemeral port");
60	    let addr = listener.local_addr().expect("local addr");
61	    std::thread::spawn(move || {
62	        actix_web::rt::System::new().block_on(async move {
63	            server
64	                .serve_with_listener(listener)
65	                .await
66	                .expect("actix serve loop");
67	        });
68	    });
69	    std::thread::sleep(std::time::Duration::from_millis(200));
70	    format!("http://{addr}")
71	}
72	
73	/// Replace the run's UUID (read from the body's `run_id` field) with a fixed
74	/// token so two otherwise-identical bodies can be byte-compared. Parsing only
75	/// locates the UUID; the substitution is a raw-text replace, so field order and
76	/// spacing are preserved (a parse-and-reserialize would hide framing drift).
77	fn normalize_run_id(body: &str) -> String {
78	    let value: serde_json::Value = serde_json::from_str(body).expect("run response is JSON");
79	    let run_id = value["run_id"].as_str().expect("run_id is a string");
80	    body.replace(run_id, RUN_ID_TOKEN)
81	}
82	
83	/// Decode the `data:` payloads of an SSE body into a `Vec` of JSON values, in
84	/// order. `event:` tag lines and blank separators are ignored.
85	fn sse_data_values(body: &str) -> Vec<serde_json::Value> {
86	    body.lines()
87	        .filter_map(|line| line.strip_prefix("data:"))
88	        .map(str::trim)
89	        .filter(|data| !data.is_empty())
90	        .map(|data| serde_json::from_str::<serde_json::Value>(data).expect("SSE data is JSON"))
91	        .collect()
92	}
